// Offline worker for the Knowledge Base. Generated by tools/sw_list.py from
// tools/sw.template.js — edit the template, then run the tool.
//
// On install it keeps every page file; afterwards it answers from that copy
// and refreshes it in the background. A new version (any file changed)
// replaces the old copy as soon as it is installed.
const VERSION = '__VERSION__';
// A name only this site uses: other projects can share the github.io address.
const PREFIX = 'cckb-';
const CACHE = `${PREFIX}${VERSION}`;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  // cache: 'reload' skips the browser's own short-term copy, so a new version
  // never keeps an old file. A file that fails is skipped, not fatal: it is
  // fetched from the network when first needed.
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.allSettled(PRECACHE.map(async (url) => {
      const response = await fetch(new Request(new URL(url, self.location), { cache: 'reload' }));
      if (response.ok) await cache.put(url, response);
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(request, { ignoreSearch: true });
    const fresh = fetch(request)
      .then((response) => {
        if (response.ok) cache.put(request, response.clone());
        return response;
      })
      .catch(() => null);
    if (cached) {
      event.waitUntil(fresh);
      return cached;
    }
    const response = await fresh;
    if (response) return response;
    // Offline and never seen: show the home page for page visits.
    if (request.mode === 'navigate') return (await cache.match('./')) ?? Response.error();
    return Response.error();
  })());
});
